import React, { useState } from "react";
import { User, Lock } from "lucide-react";
import { useNavigate } from "react-router-dom";

const SignIn = () => {

  const navigate = useNavigate();

  const [workerId, setWorkerId] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = () => {

    if(workerId && password){
      navigate("/dashboard");
    }

  };

  return (

    <div className="absolute inset-0 flex items-center justify-center bg-[#47510B]/60 backdrop-blur-md">

      <div className="bg-[#FDFAD8] border-4 border-[#47510B] rounded-[40px] shadow-[0_20px_0_0_#47510B] p-10 w-[420px]">

        <h2 className="text-4xl font-black italic text-[#47510B] uppercase mb-8">
          Worker Login
        </h2>

        <div className="space-y-5">

          <div className="relative">
            <User className="absolute left-4 top-4 text-[#47510B]/40"/>
            <input
              value={workerId}
              onChange={(e)=>setWorkerId(e.target.value)}
              placeholder="WORKER ID"
              className="w-full p-4 pl-12 rounded-2xl border-2 border-[#47510B] font-bold outline-none"
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-4 top-4 text-[#47510B]/40"/>
            <input
              type="password"
              value={password}
              onChange={(e)=>setPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full p-4 pl-12 rounded-2xl border-2 border-[#47510B] font-bold outline-none"
            />
          </div>

          <button
            onClick={handleLogin}
            className="w-full bg-[#47510B] text-[#CAD23C] font-black p-4 rounded-2xl text-xl uppercase"
          >
            Access Dashboard
          </button>

        </div>

      </div>

    </div>
  );
};

export default SignIn;
